{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [session("a", 1, True), session("b", 1, None), session("c", 1, False)]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([session("a", 1, None)]) == 0.0


def test_conversion_rate_empty():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_rate_weights_sessions_not_groups():
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 1, False), session("c", 2, None), session("d", 2, True)],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_rate_without_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_flags_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \n"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None),
    ]


def test_parse_skips_blank_whitespace_and_comments():
    lines = ["", " \t\n", "# comment", " \t# not,a,session,at,all", "x,2,1"]
    assert parse_session_log(iter(lines)) == [session("x", 2, True)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parse_errors_report_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "a,1,1", " \t", bad_line])


def test_dedupe_duplicate_ids_keeps_last_input_record():
    earlier = session("a", 9, True)
    later = session("a", 2, None)
    events = [earlier, session("b", 2, True), session("c", 1, False), later]
    assert dedupe_sessions(events) == [events[2], later, events[1]]
    assert events[0] == earlier


def test_dedupe_empty():
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = [
        session("a", 0, True), session("b", 1, True), session("c", 1, True),
        session("d", 2, False), session("e", 2, None), session("f", 4, True),
        session("g", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 4) == [1]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (10, 2)])
def test_campaign_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [
            session("b", 4, True), session("c", 5, None), session("d", 2, False),
            session("e", 2, False), session("f", 2, False),
        ],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (2, ["best", "a"]), (10, ["best", "a", "z", "zero"])])
def test_top_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "empty": [],
        "zero": [session("c", 1, False)],
        "a": [session("d", 1, False), session("e", 1, True)],
        "best": [session("f", 1, True)],
    }
    assert top_converting_groups(groups, n) == expected


def test_top_groups_without_sessions():
    assert top_converting_groups({}, 3) == []
    assert top_converting_groups({"empty": []}, 3) == []


def test_group_rates_sorted_keys_and_empty_group_none():
    groups = {
        "z": [session("a", 1, True), session("b", 1, None)],
        "empty": [],
        "a": [session("c", 1, False)],
    }
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.0, "empty": None, "z": 0.5}
    assert list(rates) == ["a", "empty", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 0, 3, 4, 5, 0, 1], 3),
     ([1, -1, 1], 1), ([1, 2, 3], 3)],
)
def test_longest_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
